// Authored Practice batches. Content here is deliberately separate from the
// lesson-derived activities so coverage reports can distinguish authored work.
const authoredExercise = (data) => ({
    ...data,
    career: "Full Stack Developer",
    phase: data.phase || "Web Fundamentals",
    kind: data.kind || "written",
    simplerProblem: data.simplerProblem || data.problemStatement,
    conceptsToReview: data.conceptsToReview || [data.topic],
    prerequisites: data.prerequisites || [],
    learningObjectives: data.learningObjectives || [
        `Apply ${data.topic} to the described scenario.`,
        `Justify the result using the supplied evidence and constraints.`
    ],
    requirements: data.requirements,
    examples: data.examples,
    tests: data.tests,
    hints: data.hints,
    approach: data.approach,
    walkthrough: data.walkthrough,
    solutionCode: data.solutionCode,
    solutionLines: data.solutionLines || [data.approach, data.walkthrough, data.solutionCode],
    commonMistakes: data.commonMistakes || [],
    followUp: data.followUp,
    completionCriteria: data.completionCriteria
});

const exercise = (topic, id, title, difficulty, estimatedTime, problemStatement, requirements, examples, hints, approach, walkthrough, solutionCode, followUp, completionCriteria, extra = {}) => authoredExercise({
    topic, phase: extra.phase, id, title, difficulty, estimatedTime, problemStatement, requirements, examples,
    tests: examples.map((example, index) => ({ name: `Scenario ${index + 1}`, input: example.input, expected: example.output })),
    hints, approach, walkthrough, solutionCode, followUp, completionCriteria,
    starterCode: extra.starterCode || "Write your response here. Include your reasoning and the evidence or output requested.",
    language: extra.language || "Written analysis",
    commonMistakes: extra.commonMistakes || [],
    conceptsToReview: extra.conceptsToReview || [topic],
    learningObjectives: extra.learningObjectives || [
        `Explain and apply ${topic} in a realistic web request scenario.`,
        `Evaluate the result against the exercise's constraints and test cases.`
    ],
    prerequisites: extra.prerequisites || [],
    complexity: extra.complexity
});

const htmlCssExercise = (...args) => {
    const extra = args.pop() || {};
    return exercise(...args, { ...extra, phase: "HTML & CSS" });
};

